/**
 * Fact audit Round 2, group F (Career Finder) — Comp B return, 2026-10-22.
 *
 * careerIndex.json is GENERATED by scripts/build-career-index.py from the owner
 * workbook plus scripts/career-index-overrides.json. Every fix below lives in the
 * overrides file, so this pins both: the shipped index says the corrected thing,
 * and the overrides carry it so a rebuild cannot silently undo it.
 */
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { describe, it } from 'node:test';

const read = (p: string) => readFileSync(new URL(`../${p}`, import.meta.url), 'utf8').replace(/\r\n/g, '\n');

type Raw = { id: string; t: string; alt?: string[]; st: number; wm: number; prep: number; reg?: 1; pe?: 1 };
const index = JSON.parse(read('src/data/careerIndex.json')) as {
  enums: { preparation: string[]; workModel: string[]; status: string[] };
  careers: Raw[];
};
const ov = JSON.parse(read('scripts/career-index-overrides.json')) as {
  preparation: Record<string, string>; workModel: Record<string, string>; regulated: string[];
  status: Record<string, string>; removeAlternates: Record<string, string[]>; craftFamilies: string[];
};
const byTitle = (t: string) => {
  const c = index.careers.find((x) => x.t === t);
  assert.ok(c, t);
  return c;
};
const prep = (t: string) => index.enums.preparation[byTitle(t).prep];
const wm = (t: string) => index.enums.workModel[byTitle(t).wm];

describe('mixing & mastering: no "bachelor’s degree common" default (F091130–F091155, F091175)', () => {
  for (const t of ['Mixing Engineer', 'Mastering Engineer', 'Vinyl Mastering Engineer', 'Sample-Library Recording Engineer']) {
    it(t, () => assert.equal(prep(t), "Varies: portfolio/experience, certificate, associate, or bachelor's pathway"));
  }
  it('assistants get the hands-on line', () => assert.match(prep('Assistant Mastering Engineer'), /^Hands-on training/));
  it('music mix engineers are mostly freelance', () => {
    assert.equal(wm('Mixing Engineer'), 'Often freelance/contract; staff roles also exist');
    assert.equal(wm('Stem Mixing Engineer'), 'Often freelance/contract; staff roles also exist');
  });
  it('the family is a craft family in the overrides', () => assert.ok(ov.craftFamilies.includes('Mixing & Mastering')));
});

describe('degree, licence and clinical facts', () => {
  it('PE-flagged acoustics consultants no longer offer a certificate/associate route (F091536…)', () => {
    for (const t of ['Acoustical Consultant', 'Noise-Control Consultant', 'Principal Acoustical Consultant']) {
      assert.equal(byTitle(t).pe, 1, t);
      assert.doesNotMatch(prep(t), /associate|^Varies/, t);
      assert.match(prep(t), /^Bachelor's degree common/, t);
    }
  });
  it('manufacturing and quality ENGINEERS need a degree (F091876–F091885)', () => {
    for (const t of ['Manufacturing Engineer — Audio Products', 'Audio Quality Engineer', 'Supplier Quality Engineer — Audio', 'Failure-Analysis Engineer — Audio']) {
      assert.match(prep(t), /^Bachelor's degree common/, t);
    }
  });
  it('conservators: graduate degree (F091911, F091920)', () => {
    for (const t of ['Audiovisual Conservator', 'Magnetic-Tape Conservator']) assert.match(prep(t), /^Graduate degree commonly expected/, t);
  });
  it('patent attorney: science background + registration exam, not "audio/music specialization" (F091986)', () => {
    assert.match(prep('Audio Technology Patent Attorney'), /Science or engineering degree, law degree, bar admission, and the patent office registration exam/);
    assert.doesNotMatch(prep('Audio Technology Patent Attorney'), /audio\/music specialization/);
  });
  it('school music directors: degree + state teaching license (F092585–F092587)', () => {
    for (const t of ['Band Director', 'Orchestra Director', 'School Choir Director']) {
      assert.match(prep(t), /state teaching license for public-school posts/, t);
      assert.doesNotMatch(prep(t), /business training/, t);
      assert.equal(byTitle(t).reg, 1, t);
    }
  });
  it('clinical speech/hearing rehab roles: graduate clinical training, never certificate/associate (F092647–F092655)', () => {
    for (const t of ['Auditory-Verbal Therapist', 'Cochlear-Implant Rehabilitation Specialist', 'Hearing Rehabilitation Specialist', 'Clinical Vocal-Fold Imaging Specialist']) {
      assert.match(prep(t), /^Graduate clinical training and jurisdictional licensure/, t);
    }
    assert.equal(byTitle('Hearing Rehabilitation Specialist').reg, 1);
  });
  it('sonar ENGINEERS are degree roles, not military-trained (F091614)', () => {
    for (const t of ['Sonar Systems Engineer', 'Sonar Signal-Processing Engineer']) assert.doesNotMatch(prep(t), /Military/, t);
  });
  it('hearing-aid specialists read as regulated titles (F091664–F091666)', () => {
    for (const t of ['Hearing Instrument Specialist', 'Hearing-Aid Specialist', 'Hearing-Aid Fitting Specialist']) {
      assert.equal(index.enums.status[byTitle(t).st], 'Regulated/credentialed title', t);
    }
  });
  it('"hearing specialist" is no longer an alternate name for Audiologist (F091650)', () => {
    assert.ok(!(byTitle('Audiologist').alt ?? []).includes('hearing specialist'));
    assert.deepEqual(byTitle('Audiologist').alt, ['clinical audiologist']);
  });
});

describe('work model', () => {
  it('Radio DJ leads with staff roles (F092157)', () => assert.equal(wm('Radio DJ'), 'Staff roles common; consulting/contract options vary'));
  it('Military Band Musician is uniformed service, entered by audition + enlistment (F092375)', () => {
    assert.equal(wm('Military Band Musician'), 'Full-time uniformed military service');
    assert.match(prep('Military Band Musician'), /^Audition and enlistment/);
    assert.doesNotMatch(prep('Military Band Musician'), /credits/);
  });
  it('sonar operators are not freelance (F092846)', () => {
    for (const t of ['Sonar Operator', 'Sonar Systems Operator', 'Anti-Submarine Warfare Acoustic Operator', 'Maritime Patrol Acoustic Operator']) {
      assert.doesNotMatch(wm(t), /freelance/, t);
    }
  });
  it('business owners are self-employed, not freelance (F092937)', () => {
    for (const t of ['Music Store Owner', 'Recording Studio Owner', 'Studio Owner']) assert.equal(wm(t), 'Self-employed business owner', t);
    assert.doesNotMatch(wm('Audio Product Owner'), /freelance/);
  });
  it('workbook work-model codes 0-3 never move (new strings are appended)', () => {
    assert.deepEqual(index.enums.workModel.slice(0, 4), [
      'Staff roles common; consulting/contract options vary',
      'Staff, freelance, or project-based depending on sector',
      'Often freelance/contract; staff roles also exist',
      'Project, venue, tour, or contract work common',
    ]);
  });
});

describe('a rebuild keeps the fixes (they live in the overrides, not only the generated JSON)', () => {
  it('Round 1 patent-role fixes moved into the overrides', () => {
    assert.match(ov.preparation['Audio Patent Agent'], /registration exam/);
    assert.match(ov.preparation['Patent Examiner — Audio Technology'], /^Bachelor's degree in engineering or science required/);
    assert.equal(ov.workModel['Patent Examiner — Audio Technology'], 'Staff roles at a government patent office');
  });
  it('Round 2 fixes are in the overrides', () => {
    assert.ok(ov.regulated.includes('Hearing Rehabilitation Specialist'));
    assert.deepEqual(ov.removeAlternates.Audiologist, ['hearing specialist']);
    assert.equal(ov.status['Hearing Instrument Specialist'], 'Regulated/credentialed title');
    assert.match(ov.preparation['Band Director'], /state teaching license/);
  });
  it('the build script knows the appended work models and the new hooks', () => {
    const src = read('scripts/build-career-index.py');
    for (const s of ['Staff roles at a government patent office', 'Full-time uniformed military service', 'Self-employed business owner']) assert.ok(src.includes(`'${s}'`), s);
    for (const hook of ["ov.get('status'", "ov.get('professionalEngineer'", "ov.get('removeAlternates'"]) assert.ok(src.includes(hook), hook);
  });
});
